import {
  DataTexture,
  LinearFilter,
  LinearMipMapLinearFilter,
  NoColorSpace,
  RedFormat,
  TextureLoader,
  UnsignedByteType,
  type Texture,
  type WebGLRenderer
} from 'three'

import type { LightTileRequest, LightTileResponse } from './nightLightDecode.worker'

/**
 * Streams NASA Black Marble night lights at a resolution that depends on
 * distance: a global ~5 km/px base texture, plus a 4096×4096 detail window
 * (~610 m/px, 8×8 tiles of 2.8125°, ~1,500 km across) around the view,
 * filled from tiles generated by scripts/build-night-lights.mjs and
 * recentered as the view moves. Tiles missing from the manifest are dark
 * (ocean, wilderness); tiles not loaded yet fall back to the base.
 */

export interface NightLightsManifest {
  version: 1
  credit: string
  base: { url: string; width: number; height: number }
  detail: {
    level: number
    tileSize: number
    tileDegrees: number
    columns: number
    rows: number
    tiles: string[]
  }
}

const ROOT = '/night-lights'
export const WINDOW_TILES = 8
const MAX_CACHED_TILES = 192
const CONCURRENT_LOADS = 6

/** Seconds a newly arrived light map tile takes to fade in. */
const TILE_FADE_S = 0.8

export class NightLightTiles {
  manifest: NightLightsManifest | null = null
  base: Texture | null = null
  readonly detail: DataTexture
  /**
   * Window origin in global tile coordinates (column, row), and 1 where a
   * window tile holds final data (loaded or known empty), as of the last
   * upload: what the shader may use. Published only with the texture, or
   * the shader reads the old window's image at the new place (mostly
   * dark: every light in view went out until the next upload).
   */
  readonly origin = { x: -1000, y: -1000 }
  readonly loaded = new Float32Array(WINDOW_TILES * WINDOW_TILES)
  /** The same, as being filled (ahead of the uploaded texture). */
  private readonly windowOrigin = { x: -1000, y: -1000 }
  private readonly windowLoaded = new Float32Array(WINDOW_TILES * WINDOW_TILES)
  /** `loaded` fades towards this (tiles fade in rather than pop). */
  private readonly targetLoaded = new Float32Array(WINDOW_TILES * WINDOW_TILES)

  private readonly data: Uint8Array
  private available = new Set<string>()
  private readonly cache = new Map<string, Uint8Array>()
  private readonly queue: string[] = []
  private inFlight = 0
  private dirty = false
  private failed = false
  /**
   * Window slots filled since the last upload. Only these are uploaded
   * (a 512² region each); the whole 4096² window, with its mipmaps, was
   * re-uploaded for every arriving tile, a hitch each time.
   */
  private readonly dirtySlots = new Set<number>()
  /** The whole window must go up (first upload, recentred). */
  private fullUpload = true
  private worker: Worker | null = null
  private nextRequest = 0
  private readonly requests = new Map<number, (gray: Uint8Array | null) => void>()

  constructor() {
    const size = 512 * WINDOW_TILES
    this.data = new Uint8Array(size * size)
    const texture = new DataTexture(this.data, size, size, RedFormat, UnsignedByteType)
    texture.minFilter = LinearMipMapLinearFilter
    texture.magFilter = LinearFilter
    texture.generateMipmaps = true
    texture.flipY = false
    texture.unpackAlignment = 1
    texture.colorSpace = NoColorSpace
    texture.anisotropy = 8
    this.detail = texture
  }

  async load(): Promise<boolean> {
    if (this.manifest != null || this.failed) return this.manifest != null
    try {
      const response = await fetch(`${ROOT}/manifest.json`)
      if (!response.ok) throw new Error(String(response.status))
      this.manifest = (await response.json()) as NightLightsManifest
    } catch {
      this.failed = true
      console.info(
        '[night-lights] no data; run `pnpm --filter @windowseat/client night-lights` to build it'
      )
      return false
    }
    this.available = new Set(this.manifest.detail.tiles)
    const base = await new TextureLoader().loadAsync(`${ROOT}/${this.manifest.base.url}`)
    base.flipY = false
    base.colorSpace = NoColorSpace
    base.anisotropy = 8
    // One channel (the map is gray): a quarter of the GPU memory of RGBA
    // (45 instead of 180 MB at 8192×4096), and the decoded image is dropped
    // once uploaded.
    base.format = RedFormat
    base.onUpdate = () => {
      ;(base.source as { data: unknown }).data = null
      base.onUpdate = null
    }
    base.needsUpdate = true
    this.base = base
    return true
  }

  /** Recenters the detail window on (lat, lon) if it drifted ≥ 2 tiles. */
  setCenter(lat: number, lon: number): void {
    const m = this.manifest
    if (m == null) return
    const deg = m.detail.tileDegrees
    const cx = Math.floor((lon + 180) / deg)
    const cy = Math.floor((90 - lat) / deg)
    const half = WINDOW_TILES / 2
    if (Math.abs(cx - (this.windowOrigin.x + half)) < 2 && Math.abs(cy - (this.windowOrigin.y + half)) < 2) {
      return
    }
    this.windowOrigin.x = cx - half
    this.windowOrigin.y = Math.max(0, Math.min(m.detail.rows - WINDOW_TILES, cy - half))
    this.data.fill(0)
    this.windowLoaded.fill(0)
    this.queue.length = 0
    this.fullUpload = true
    // Nearest tiles first.
    const order: Array<[number, number, number]> = []
    for (let j = 0; j < WINDOW_TILES; ++j) {
      for (let i = 0; i < WINDOW_TILES; ++i) {
        order.push([i, j, (i - half + 0.5) ** 2 + (j - half + 0.5) ** 2])
      }
    }
    order.sort((a, b) => a[2] - b[2])
    for (const [i, j] of order) this.place(i, j)
    // Upload now: the new origin must not reach the shader before its image.
    this.upload(null)
  }

  /** Global tile key for window slot (i, j), wrapping longitude. */
  private keyFor(i: number, j: number): string {
    const columns = this.manifest!.detail.columns
    const x = (((this.windowOrigin.x + i) % columns) + columns) % columns
    return `${x}_${this.windowOrigin.y + j}`
  }

  private place(i: number, j: number): void {
    const key = this.keyFor(i, j)
    if (!this.available.has(key)) {
      this.windowLoaded[j * WINDOW_TILES + i] = 1
      return
    }
    const cached = this.cache.get(key)
    if (cached != null) {
      this.blit(i, j, cached)
      return
    }
    this.queue.push(key)
    this.pump()
  }

  private pump(): void {
    while (this.inFlight < CONCURRENT_LOADS && this.queue.length > 0) {
      const key = this.queue.shift()!
      ++this.inFlight
      void this.fetchTile(key).finally(() => {
        --this.inFlight
        this.pump()
      })
    }
  }

  private decode(url: string, size: number): Promise<Uint8Array | null> {
    if (this.worker == null) {
      this.worker = new Worker(new URL('./nightLightDecode.worker.ts', import.meta.url), {
        type: 'module',
        name: 'night-light-tiles'
      })
      this.worker.onmessage = (event: MessageEvent<LightTileResponse>) => {
        const resolve = this.requests.get(event.data.id)
        this.requests.delete(event.data.id)
        if (event.data.error != null) console.warn('[night-lights] tile:', event.data.error)
        resolve?.(event.data.gray)
      }
    }
    const id = this.nextRequest++
    return new Promise(resolve => {
      this.requests.set(id, resolve)
      const request: LightTileRequest = { id, url, size }
      this.worker!.postMessage(request)
    })
  }

  private async fetchTile(key: string): Promise<void> {
    const m = this.manifest!
    try {
      const gray = await this.decode(`${ROOT}/${m.detail.level}/${key}.jpg`, m.detail.tileSize)
      if (gray == null) return
      this.cache.set(key, gray)
      if (this.cache.size > MAX_CACHED_TILES) {
        this.cache.delete(this.cache.keys().next().value!)
      }
      // Still in the window?
      for (let j = 0; j < WINDOW_TILES; ++j) {
        for (let i = 0; i < WINDOW_TILES; ++i) {
          if (this.keyFor(i, j) === key) this.blit(i, j, gray)
        }
      }
    } catch (error) {
      console.warn(`[night-lights] tile ${key}:`, error)
    }
  }

  private blit(i: number, j: number, gray: Uint8Array): void {
    const size = 512
    const stride = size * WINDOW_TILES
    for (let y = 0; y < size; ++y) {
      this.data.set(gray.subarray(y * size, (y + 1) * size), (j * size + y) * stride + i * size)
    }
    this.windowLoaded[j * WINDOW_TILES + i] = 1
    this.dirtySlots.add(j * WINDOW_TILES + i)
    this.dirty = true
  }

  /** Uploads the window if tiles arrived (call at most a few times a second). */
  flush(renderer: WebGLRenderer): void {
    if (this.dirty) this.upload(renderer)
  }

  /**
   * Publishes the window: arrived tiles' regions only when it's already on
   * the GPU (renderer given), else the whole of it with the next render.
   */
  private upload(renderer: WebGLRenderer | null): void {
    this.dirty = false
    const uploaded = renderer != null && (renderer.properties.get(this.detail) as { __webglTexture?: WebGLTexture }).__webglTexture
    if (this.fullUpload || renderer == null || uploaded == null) {
      this.detail.needsUpdate = true
      this.fullUpload = false
    } else {
      const gl = renderer.getContext() as WebGL2RenderingContext
      renderer.state.bindTexture(gl.TEXTURE_2D, uploaded)
      const size = 512
      const stride = size * WINDOW_TILES
      gl.pixelStorei(gl.UNPACK_ALIGNMENT, 1)
      gl.pixelStorei(gl.UNPACK_FLIP_Y_WEBGL, false)
      gl.pixelStorei(gl.UNPACK_PREMULTIPLY_ALPHA_WEBGL, false)
      gl.pixelStorei(gl.UNPACK_ROW_LENGTH, stride)
      for (const slot of this.dirtySlots) {
        const i = slot % WINDOW_TILES
        const j = Math.floor(slot / WINDOW_TILES)
        gl.pixelStorei(gl.UNPACK_SKIP_PIXELS, i * size)
        gl.pixelStorei(gl.UNPACK_SKIP_ROWS, j * size)
        gl.texSubImage2D(gl.TEXTURE_2D, 0, i * size, j * size, size, size, gl.RED, gl.UNSIGNED_BYTE, this.data)
      }
      gl.pixelStorei(gl.UNPACK_ROW_LENGTH, 0)
      gl.pixelStorei(gl.UNPACK_SKIP_PIXELS, 0)
      gl.pixelStorei(gl.UNPACK_SKIP_ROWS, 0)
      gl.generateMipmap(gl.TEXTURE_2D)
    }
    this.dirtySlots.clear()
    const dx = this.windowOrigin.x - this.origin.x
    const dy = this.windowOrigin.y - this.origin.y
    if (dx !== 0 || dy !== 0) {
      // Recentred: tiles still in the window keep how far they had faded in
      // (they're still there); the rest start from the base map.
      const previous = Float32Array.from(this.loaded)
      for (let j = 0; j < WINDOW_TILES; ++j) {
        for (let i = 0; i < WINDOW_TILES; ++i) {
          const pi = i + dx
          const pj = j + dy
          const inside = pi >= 0 && pj >= 0 && pi < WINDOW_TILES && pj < WINDOW_TILES
          this.loaded[j * WINDOW_TILES + i] = inside ? previous[pj * WINDOW_TILES + pi]! : 0
        }
      }
      this.origin.x = this.windowOrigin.x
      this.origin.y = this.windowOrigin.y
    }
    this.targetLoaded.set(this.windowLoaded)
  }

  /** Fades newly uploaded tiles in (call every frame). */
  tick(delta: number): void {
    const step = delta / TILE_FADE_S
    for (let i = 0; i < this.loaded.length; ++i) {
      const target = this.targetLoaded[i]!
      const value = this.loaded[i]!
      if (value !== target) this.loaded[i] = value < target ? Math.min(target, value + step) : target
    }
  }

  dispose(): void {
    this.worker?.terminate()
    this.detail.dispose()
    this.base?.dispose()
  }
}
